def normalize_automotive_stt_text(text: str) -> str:
    """
    اصلاح هوشمند اشتباهات رایج گفتار به نوشتار فارسی (STT) در حوزه لنت ترمز و لوازم یدکی:
    - تبدیل «باشیم» / «با سیم» / «باسیم» به «با شیم»
    - تبدیل «بدون سیم» / «بی سیم» / «بی‌سیم» به «بدون شیم»
    - تبدیل «شیم دار» / «سیم دار» / «سیم‌دار» به «با شیم»
    - استانداردسازی نام خودروها و ضخامت‌ها (۵ میل / ۶ میل)
    """
    if not text:
        return ""
    t = text.strip()

    replacements = [
        # اصلاح اشتباهات رایج کلمه «شیم» در ویس فارسی
        (r"\bباشیم\b", "با شیم"),
        (r"\bبا\s*سیم\b", "با شیم"),
        (r"\bباسیم\b", "با شیم"),
        (r"\bبا\s*شین\b", "با شیم"),
        (r"\bباشین\b", "با شیم"),
        (r"\bسیم\s*دار\b", "با شیم"),
        (r"\bسیم‌دار\b", "با شیم"),
        (r"\bشیم\s*دار\b", "با شیم"),
        (r"\bشیم‌دار\b", "با شیم"),
        (r"\bبدون\s*سیم\b", "بدون شیم"),
        (r"\bبدون\s*شین\b", "بدون شیم"),
        (r"\bبی\s*سیم\b", "بدون شیم"),
        (r"\bبی‌سیم\b", "بدون شیم"),
        (r"\bبی\s*شیم\b", "بدون شیم"),
        (r"\bبی‌شیم\b", "بدون شیم"),
        # اصلاح نام خودروها و ضخامت‌ها در گفتار
        (r"\bپرایدی\b", "پراید"),
        (r"\bتیبایی\b", "تیبا"),
        (r"\bپژویی\b", "پژو"),
        (r"\bسمندی\b", "سمند"),
        (r"\bنیسانی\b", "نیسان"),
        (r"\bپیکانی\b", "پیکان"),
        (r"\bمزدایی\b", "مزدا"),
        (r"\bام\s*وی\s*ام\b", "MVM"),
        (r"\bایکس\s*۳۳\b", "X33"),
        (r"\bایکس\s*33\b", "X33"),
        (r"\bایکس\s*۲۲\b", "X22"),
        (r"\bایکس\s*22\b", "X22"),
        (r"\bایکس\s*۵۵\b", "X55"),
        (r"\bایکس\s*55\b", "X55"),
        (r"\bاس\s*۵\b", "S5"),
        (r"\bاس\s*5\b", "S5"),
        (r"\bاس\s*۳\b", "S3"),
        (r"\bاس\s*3\b", "S3"),
        (r"\bجی\s*۵\b", "J5"),
        (r"\bجی\s*5\b", "J5"),
        (r"\bجی\s*۴\b", "J4"),
        (r"\bجی\s*4\b", "J4"),
        (r"\bتی\s*۸\b", "T8"),
        (r"\bتی\s*8\b", "T8"),
        (r"\bشش\s*میل\b", "۶ میل"),
        (r"\bشیش\s*میل\b", "۶ میل"),
        (r"\bپنج\s*میل\b", "۵ میل"),
    ]
    for pattern, repl in replacements:
        t = re.sub(pattern, repl, t)

    t = re.sub(r"\s+", " ", t).strip()
    return t


def format_person_with_honorific(name_str: str, gender: str = "") -> str:
    """
    افزودن «جناب آقای» برای آقایان و «سرکار خانم» برای خانم‌ها بدون اضافه کردن هیچ پسوند اضافی
    """
    t = (name_str or "").strip()
    if not t or t == "مشتری گرامی":
        return "مشتری گرامی"

    is_female = str(gender).lower().strip() in ("female", "woman", "f", "زن", "خانم")
    words = re.split(r"[\s\-–—_،,]+", t)
    if any(w in FEMALE_INDICATORS for w in words):
        is_female = True

    if is_female:
        if t.startswith("سرکار خانم"):
            return t
        for prefix in ["جناب خانم", "سرکار خانم", "خانم", "بانو", "سرکار"]:
            if t.startswith(prefix):
                rest = t[len(prefix):].strip()
                return f"سرکار خانم {rest}"
        return f"سرکار خانم {t}"
    else:
        if (
            t.startswith("جناب آقای")
            or t.startswith("جناب سرهنگ")
            or t.startswith("جناب دکتر")
            or t.startswith("جناب مهندس")
        ):
            return t
        for prefix in ["جناب آقای", "جناب اقای", "آقای", "اقای", "جناب"]:
            if t.startswith(prefix):
                rest = t[len(prefix):].strip()
                if rest.startswith("آقای") or rest.startswith("اقای"):
                    rest = rest[4:].strip()
                if rest.startswith("سرهنگ") or rest.startswith("دکتر") or rest.startswith("مهندس"):
                    return f"جناب {rest}"
                return f"جناب آقای {rest}"
        return f"جناب آقای {t}"


def build_final_customer_title(parsed: dict, source_text: str = "") -> str:
    """
    ساخت عنوان نهایی مشتری:
    - برای آقایان «جناب آقای ...» و برای خانم‌ها «سرکار خانم ...»
    - فقط و فقط اگر کاربر نام فروشگاه / لوازم یدکی را در سفارش گفته باشد، بعد از نام مشتری با « – » اضافه می‌شود.
    """
    gender = parsed.get("customer_gender", "")
    raw_name = (parsed.get("customer_name") or parsed.get("customer_title") or "").strip()
    shop_name = (parsed.get("shop_name") or "").strip()

    # اگر مدل به اشتباه در customer_name خودش «– لوازم یدکی ...» گذاشته باشد، جدایش می‌کنیم
    for sep in [" – ", " - ", " — ", "–", "-"]:
        if sep in raw_name:
            parts = [p.strip() for p in raw_name.split(sep, 1)]
            raw_name = parts[0]
            if not shop_name and len(parts) > 1:
                shop_name = parts[1]
            break

    person_formatted = format_person_with_honorific(raw_name, gender)

    # بررسی دقیق: آیا واقعاً نام فروشگاه یا لوازم یدکی ذکر شده است؟
    if shop_name in ("null", "None", "ندارد", "-", "—", "...", "فروشگاه", "لوازم یدکی"):
        shop_name = ""

    # اگر متن منبع (پیام متنی یا متن ویس) را داریم، فقط زمانی shop_name را نگه می‌داریم که کاربر
    # واقعاً کلمات فروشگاه/لوازم یدکی/بازرگانی/پخش و... را در پیامش گفته باشد
    if source_text and shop_name:
        shop_keywords = ["لوازم یدکی", "یدکی", "فروشگاه", "بازرگانی", "پخش", "تعمیرگاه", "کلینیک", "مغازه"]
        if not any(kw in source_text for kw in shop_keywords):
            shop_name = ""

    if shop_name:
        return f"{person_formatted} – {shop_name}"
    return person_formatted


# ==============================================================================
# ۵. بارگذاری لیست قیمت از فایل اکسل
# ==============================================================================
def load_catalog_from_excel(excel_path: str):
    if not os.path.exists(excel_path):
        raise FileNotFoundError(f"فایل اکسل در مسیر '{excel_path}' یافت نشد.")

    wb = openpyxl.load_workbook(excel_path, data_only=True)
    ws = wb.active
    catalog = []

    for r in range(3, ws.max_row + 1):
        row_id = ws.cell(r, 2).value
        wva = ws.cell(r, 3).value
        name = ws.cell(r, 4).value
        price_no_shim = ws.cell(r, 5).value
        price_with_shim = ws.cell(r, 6).value

        if not wva or not name:
            continue

        def parse_price(v):
            if v is None:
                return None
            s = to_en_str(str(v)).replace(",", "").strip()
            if s in ("-", "", "None"):
                return None
            try:
                return int(float(s))
            except ValueError:
                return None

        p_no = parse_price(price_no_shim)
        p_yes = parse_price(price_with_shim)

        catalog.append(
            {
                "row_id": str(row_id).strip(),
                "wva": str(wva).strip(),
                "name": str(name).strip(),
                "price_no_shim": p_no,
                "price_with_shim": p_yes,
            }
        )
    return catalog


def format_catalog_for_prompt(catalog) -> str:
    lines = ["ردیف | کد فنی (WVA) | نام قطعه خودرو | قیمت بدون شیم (ریال) | قیمت با شیم (ریال)"]
    for item in catalog:
        p_no = f"{item['price_no_shim']:,}" if item["price_no_shim"] else "ناموجود"
        p_yes = f"{item['price_with_shim']:,}" if item["price_with_shim"] else "ناموجود"
        lines.append(
            f"{item['row_id']} | {item['wva']} | {item['name']} | {p_no} | {p_yes}"
        )
    return "\n".join(lines)


# ==============================================================================
# ۶. ساخت پرامپت سیستم و پردازش متن، عکس و ویس با OpenRouter
# ==============================================================================
def build_system_prompt(catalog: list) -> str:
    catalog_text = format_catalog_for_prompt(catalog)
    today_str = get_today_jalali()

    return f"""شما دستیار هوشمند صدور فاکتور «شرکت کیالنت البرز نور» هستید.
وظیفه شما تحلیل درخواست کاربر (از روی متن، ویس یا تصویر سفارش/دست‌نویس) و استخراج دقیق اطلاعات فاکتور یا پیش‌فاکتور بر اساس لیست قیمت زیر است:

=== لیست قیمت رسمی (اکسل) ===
{catalog_text}

=== قوانین بسیار مهم ===
1. نوع سند (`doc_type`): اگر کاربر کلمه «فاکتور» را به کار برد و نگفت پیش‌فاکتور، مقدار را `"فاکتور"` بگذارید. اگر گفت «پیش‌فاکتور» یا مشخص نکرد، `"پیش‌فاکتور"` بگذارید.
2. جنسیت مشتری (`customer_gender`) و نام شخص مشتری (`customer_name`):
   - فقط نام شخص مشتری را در `customer_name` بگذارید.
   - اگر مشتری آقا است، `customer_gender` را `"male"` بگذارید و نام را با `"جناب آقای ..."` بنویسید (مثال: `"جناب آقای رضایی"`).
   - اگر مشتری خانم است، `customer_gender` را `"female"` بگذارید و نام را با `"سرکار خانم ..."` بنویسید (مثال: `"سرکار خانم محمدی"`).
3. نام فروشگاه / لوازم یدکی (`shop_name`):
   - **بسیار مهم:** فقط و فقط اگر کاربر صراحتاً در پیام خود عبارت «لوازم یدکی ...» یا «فروشگاه ...» را ذکر کرده بود، آن را در `shop_name` بنویسید (مثلاً `"لوازم یدکی رادمهر"`).
   - اگر کاربر فقط نام شخص را گفت و نام لوازم یدکی یا مغازه را نگفت، مقدار `shop_name` را حتماً رشته خالی `""` بگذارید و از خودتان چیزی اضافه نکنید!
4. تاریخ (`date`): اگر کاربر تاریخ ذکر کرد آن را بنویسید، در غیر این صورت تاریخ امروز یعنی `"{today_str}"` را قرار دهید.
5. تطبیق کالاها (`items`):
   - برای هر قلم سفارش، شماره ردیف دقیق (`row_id`) را از روی **نام قطعه خودرو** در لیست بالا پیدا کنید.
   - اگر کالا دو ضخامت ۵ میل و ۶ میل دارد (مثل تیبا/ریو ۷.۱ و ۷.۲، کوییک/ساینا، رانا و شاهین) و کاربر ضخامت را ذکر کرد (مثلاً «۶ میل» یا «۵ میل»)، حتماً ردیف دقیق همان ضخامت (مثلاً `7.2` برای تیبا/ریو ۶ میل) را انتخاب کنید.
   - وضعیت شیم (`with_shim`): برای **هر قلم کالا به صورت جداگانه** بررسی کنید! اگر برای آن کالا عبارت «با شیم»، «باشیم»، «شیم‌دار» یا «با سیم» ذکر شده بود حتماً `with_shim` را `true` بگذارید؛ و اگر «بدون شیم»، «بدون سیم» یا «بی‌شیم» ذکر شده بود `false` بگذارید.
   - نام نمایشی کالا در جدول (`display_name`): اگر `with_shim` برابر `true` است عبارت `با شیم` را در انتهای نام قطعه اضافه کنید (مگر اینکه کاربر صراحتاً بدون شیم خواسته باشد).
6. خروجی شما باید **فقط و فقط یک JSON معتبر** بدون هیچ توضیح اضافه‌ای باشد با ساختار زیر:
{{
  "doc_type": "پیش‌فاکتور" یا "فاکتور",
  "customer_gender": "male" یا "female",
  "customer_name": "جناب آقای ..." یا "سرکار خانم ...",
  "shop_name": "لوازم یدکی ..." یا "",
  "date": "{today_str}",
  "invoice_no": ".........................",
  "items": [
    {{
      "row_id": "30",
      "wva": "WVA 80176",
      "display_name": "لنت ترمز جلو دیسکی جک S3 با شیم",
      "qty": 1,
      "with_shim": true
    }}
  ],
  "unavailable_warnings": []
}}"""


def parse_json_from_llm(content: str) -> dict:
    content = content.strip()
    if "```" in content:
        parts = content.split("```")
        for p in parts:
            p_clean = p.strip()
            if p_clean.startswith("json"):
                p_clean = p_clean[4:].strip()
            if p_clean.startswith("{") and p_clean.endswith("}"):
                content = p_clean
                break
    start_idx = content.find("{")
    end_idx = content.rfind("}")
    if start_idx != -1 and end_idx != -1:
        content = content[start_idx : end_idx + 1]
    return json.loads(content)


def _has_valid_gemini_key() -> bool:
    k = (RUNTIME_GEMINI_API_KEY or "").strip()
    return bool(k and k not in ("YOUR_GEMINI_API_KEY_HERE", "NONE", "null"))


def _has_valid_openrouter_key() -> bool:
    k = (OPENROUTER_API_KEY or "").strip()
    return bool(k and k not in ("YOUR_OPENROUTER_API_KEY_HERE", "NONE", "null"))


def _convert_messages_to_gemini_payload(messages: list, temperature: float = 0.0, json_mode: bool = False) -> dict:
    """تبدیل فرمت پیام‌های استاندارد (شامل متن، عکس و ویس) به فرمت رسمی Google AI Studio (Gemini API)"""
    system_texts = []
    contents = []

    for msg in messages:
        role = msg.get("role", "user")
        content = msg.get("content", "")

        if role == "system":
            if isinstance(content, str):
                system_texts.append(content)
            continue

        parts = []
        if isinstance(content, str):
            parts.append({"text": content})
        elif isinstance(content, list):
            for item in content:
                itype = item.get("type")
                if itype == "text":
                    parts.append({"text": item.get("text", "")})
                elif itype == "image_url":
                    url = item.get("image_url", {}).get("url", "")
                    if url.startswith("data:") and ";base64," in url:
                        header, b64_data = url.split(";base64,", 1)
                        mime_type = header.replace("data:", "").strip() or "image/jpeg"
                        parts.append({"inline_data": {"mime_type": mime_type, "data": b64_data}})
                elif itype == "input_audio":
                    aud = item.get("input_audio", {})
                    b64_data = aud.get("data", "")
                    fmt = aud.get("format", "ogg").lower()
                    mime_map = {
                        "ogg": "audio/ogg",
                        "mp3": "audio/mp3",
                        "wav": "audio/wav",
                        "m4a": "audio/mp4",
                    }
                    parts.append({"inline_data": {"mime_type": mime_map.get(fmt, "audio/ogg"), "data": b64_data}})

        if parts:
            gemini_role = "model" if role == "assistant" else "user"
            contents.append({"role": gemini_role, "parts": parts})

    payload = {
        "contents": contents,
        "generationConfig": {
            "temperature": temperature,
        },
    }
    if json_mode:
        payload["generationConfig"]["responseMimeType"] = "application/json"
    if system_texts:
        payload["systemInstruction"] = {
            "parts": [{"text": "\n\n".join(system_texts)}]
        }
    return payload


def _call_google_ai_studio_single(messages: list, model_name: str, temperature: float = 0.0, json_mode: bool = False) -> str:
    """فراخوانی مستقیم یک مدل رایگان در Google AI Studio"""
    if not _has_valid_gemini_key():
        raise RuntimeError("کلید GEMINI_API_KEY تنظیم نشده است.")

    keys = [k.strip() for k in RUNTIME_GEMINI_API_KEY.split(",") if k.strip()]
    last_err = None
    for api_key in keys:
        url = f"https://generativelanguage.googleapis.com/v1beta/models/{model_name}:generateContent?key={api_key}"
        payload = _convert_messages_to_gemini_payload(messages, temperature=temperature, json_mode=json_mode)
        resp = requests.post(url, json=payload, timeout=40)
        if resp.status_code != 200:
            # اگر مدل خاصی responseMimeType را پشتیبانی نکرد، بدون json_mode امتحان می‌کنیم
            if resp.status_code == 400 and json_mode:
                payload_no_mime = _convert_messages_to_gemini_payload(messages, temperature=temperature, json_mode=False)
                resp = requests.post(url, json=payload_no_mime, timeout=40)
            if resp.status_code != 200:
                logger.warning(f"Google AI Studio model {model_name} returned {resp.status_code}: {resp.text[:250]}")
                last_err = f"Gemini HTTP {resp.status_code}"
                continue

        data = resp.json()
        candidates = data.get("candidates") or []
        if not candidates:
            last_err = "Empty candidates from Gemini"
            continue
        parts = candidates[0].get("content", {}).get("parts") or []
        text_out = "".join(p.get("text", "") for p in parts).strip()
        if text_out:
            logger.info(f"✅ پاسخ با موفقیت از Google AI Studio ({model_name}) دریافت شد.")
            return text_out
    raise RuntimeError(last_err or "خطا در Google AI Studio")


def _call_openrouter_single(messages: list, model_name: str, temperature: float = 0.0) -> str:
    """فراخوانی یک مدل رایگان در OpenRouter"""
    if not _has_valid_openrouter_key():
        raise RuntimeError("کلید OPENROUTER_API_KEY تنظیم نشده است.")

    headers = {
        "Authorization": f"Bearer {OPENROUTER_API_KEY}",
        "Content-Type": "application/json",
        "HTTP-Referer": "https://t.me/KialentInvoiceBot",
        "X-Title": "Kialent Alborz Noor Invoice Bot",
    }
    payload = {
        "model": model_name,
        "messages": messages,
        "temperature": temperature,
    }
    resp = requests.post(
        "https://openrouter.ai/api/v1/chat/completions",
        headers=headers,
        json=payload,
        timeout=40,
    )
    if resp.status_code != 200:
        logger.warning(f"OpenRouter Model {model_name} returned {resp.status_code}: {resp.text[:250]}")
        raise RuntimeError(f"OpenRouter HTTP {resp.status_code}")

    data = resp.json()
    content = (data.get("choices") or [{}])[0].get("message", {}).get("content", "")
    if not content or not content.strip():
        raise RuntimeError(f"Empty response from OpenRouter {model_name}")
    logger.info(f"✅ پاسخ با موفقیت از OpenRouter ({model_name}) دریافت شد.")
    return content.strip()


def call_openrouter_models(
    messages: list, models_list: list, catalog: list, source_text: str = "", order_mode: str = "wholesale"
) -> dict:
    """
    سیستم چرخشی و جایگزینی دوطرفه (Mutual Fallback) بین OpenRouter و Google AI Studio:
    ۱. ابتدا مدل‌های اصلی رایگان OpenRouter را امتحان می‌کند.
    ۲. اگر OpenRouter شلوغ یا محدود (429/404) بود، بلافاصله سراغ مدل‌های رایگان Google AI Studio می‌رود.
    ۳. اگر Google AI Studio هم شلوغ بود، دوباره با مدل‌های جایگزین به سراغ OpenRouter برمی‌گردد.
    ۴. در نهایت در صورت نیاز یک دور نهایی دیگر Google AI Studio و OpenRouter را بررسی می‌کند.
    """
    import time

    last_error = None
    primary_or_models = models_list[:4] if len(models_list) > 4 else models_list
    secondary_or_models = models_list[4:] if len(models_list) > 4 else ["openrouter/free", "google/gemma-4-31b-it:free"]

    # ساخت مراحل چرخشی: OpenRouter (موج ۱) -> Google AI Studio (موج ۱) -> OpenRouter (موج ۲) -> Google AI Studio (موج ۲)
    waves = [
        ("openrouter", primary_or_models, 0.0),
        ("gemini", GEMINI_STUDIO_MODELS[:3], 0.0),
        ("openrouter", secondary_or_models, 1.2),
        ("gemini", GEMINI_STUDIO_MODELS[3:] + ["gemini-2.0-flash", "gemini-2.5-flash"], 1.2),
        ("openrouter", ["openrouter/free", "google/gemma-4-31b-it:free", "google/gemma-4-26b-a4b-it:free"], 1.5),
    ]

    for provider, wave_models, delay_sec in waves:
        if provider == "gemini" and not _has_valid_gemini_key():
            continue
        if provider == "openrouter" and not _has_valid_openrouter_key():
            continue
        if delay_sec > 0:
            time.sleep(delay_sec)

        for model_name in wave_models:
            try:
                if provider == "openrouter":
                    content = _call_openrouter_single(messages, model_name, temperature=0.0)
                else:
                    content = _call_google_ai_studio_single(messages, model_name, temperature=0.0, json_mode=True)

                parsed = parse_json_from_llm(content)
                return validate_and_price_order(parsed, catalog, source_text=source_text, order_mode=order_mode)
            except Exception as e:
                logger.warning(f"[{provider.upper()}] Error with {model_name}: {e}")
                last_error = str(e)
                continue

    raise RuntimeError(
        f"خطا در دریافت پاسخ از سرویس‌های هوش مصنوعی (OpenRouter / Google AI Studio): {last_error}"
    )



def format_full_catalog_with_compatibility(catalog: list, order_mode: str = "wholesale", show_prices: bool = False) -> str:
    """
    آماده‌سازی بانک اطلاعات کامل محصولات کیالنت البرز نور شامل:
    ردیف، کد فنی، نام قطعه و لیست کامل خودروهای سازگار (اشتراکات).
    در حالت سفارش عمده تا قبل از صدور پیش‌فاکتور، قیمت‌ها نمایش داده نمی‌شوند.
    """
    if order_mode == "wholesale" and not show_prices:
        lines = [
            "ردیف | کد فنی | نام لنت تولیدی کیالنت البرز نور | وضعیت موجودی | خودروهای سازگار و مشترک (اشتراکات)"
        ]
        for item in catalog:
            avail = "موجود" if (item["price_no_shim"] or item["price_with_shim"]) else "ناموجود"
            compat = get_compatible_vehicles_for_item(item["row_id"], item["name"])
            lines.append(
                f"{item['row_id']} | {item['wva']} | {item['name']} | {avail} | {compat}"
            )
        return "\n".join(lines)

    lines = [
        "ردیف | کد فنی | نام لنت تولیدی کیالنت البرز نور | قیمت بدون شیم (ریال) | قیمت با شیم (ریال) | خودروهای سازگار و مشترک (اشتراکات)"
    ]
    for item in catalog:
        p_no_base = item["price_no_shim"]
        p_yes_base = item["price_with_shim"]
        p_no_final, _ = calculate_final_unit_price(p_no_base, item["row_id"], item["name"], order_mode)
        p_yes_final, _ = calculate_final_unit_price(p_yes_base, item["row_id"], item["name"], order_mode)

        p_no_str = f"{p_no_final:,}" if p_no_final else "ناموجود"
        p_yes_str = f"{p_yes_final:,}" if p_yes_final else "ناموجود"
        compat = get_compatible_vehicles_for_item(item["row_id"], item["name"])
        lines.append(
            f"{item['row_id']} | {item['wva']} | {item['name']} | {p_no_str} | {p_yes_str} | {compat}"
        )
    return "\n".join(lines)


def answer_catalog_question(user_question: str, catalog: list, order_mode: str = "wholesale", is_vip: bool = False) -> str:
    """
    پاسخگویی هوشمند و دقیق به سوالات فنی مشتریان درباره:
    - اشتراکات لنت‌ها (اینکه هر لنت به چه ماشین‌هایی می‌خورد یا برای یک ماشین خاص چه لنتی در سبد محصولات داریم)
    - لیست لنت‌های تولیدی شرکت کیالنت البرز نور
    - شرایط فروش (حداقل خرید عمده ۲ کارتن معادل ۲۰ دست لنت و تسویه نقدی)
    """
    full_kb = format_full_catalog_with_compatibility(catalog, order_mode=order_mode, show_prices=is_vip)
    system_prompt = f"""شما کارشناس فنی و مشاور فروش رسمی «شرکت کیالنت البرز نور» (تولیدکننده لنت ترمز خودرو) هستید.
وظیفه شما پاسخگویی دقیق، محترمانه، روان و کامل به سوالات مشتریان بر اساس بانک اطلاعات رسمی کاتالوگ زیر است:

=== کاتالوگ جامع محصولات و اشتراکات لنت‌های شرکت کیالنت البرز نور ===
{full_kb}

=== قوانین و شرایط فروش شرکت ===
- حداقل خرید عمده: ۲ کارتن یا معادل ۲۰ دست لنت می‌باشد (سفارش‌های کمتر از ۱۵ دست، سفارش عمده محسوب نمی‌شوند و به سفارش خرد منتقل می‌شوند).
- نحوه تسویه: تمامی سفارشات به صورت نقدی تسویه می‌شوند.
- قیمت‌های سفارش عمده تا قبل از ثبت سفارش و صدور پیش‌فاکتور رسمی نمایش داده نمی‌شود؛ اگر مشتری در حالت عمده قیمت تک‌تک لنت‌ها را پرسید، محترمانه بگویید که کافی است لیست سفارش خود را بفرستد تا پیش‌فاکتور رسمی با قیمت روز برایش صادر شود.
- هرگز درباره درصد تفاوت قیمت خرد و عمده صحبت نکنید.
- اگر مشتری پرسید «چه لنت‌هایی دارید؟»، دسته‌بندی کامل لنت‌های تولیدی ما (ایرانی، چینی، شاسی‌بلند و وارداتی) را به صورت مرتب و خوانا معرفی کنید.
- اگر مشتری پرسید «لنت فلان ماشین به چه ماشین‌هایی می‌خورد؟» یا «برای فلان ماشین چه لنتی دارید و با چی مشترکه؟»، دقیقاً از ستون «خودروهای سازگار و مشترک (اشتراکات)» در جدول بالا استفاده کنید و کد فنی و تمام خودروهای مشترک آن را کامل بنویسید.
- پاسخ را با فرمت زیبا، بولت‌بندی شده و اعداد فارسی بنویسید."""

    messages = [
        {"role": "system", "content": system_prompt},
        {"role": "user", "content": user_question},
    ]

    import time
    last_error = None
    waves = [
        ("openrouter", FREE_TEXT_MODELS_PRIMARY, 0.0),
        ("gemini", GEMINI_STUDIO_MODELS[:3], 0.0),
        ("openrouter", FREE_TEXT_MODELS_SECONDARY, 1.0),
        ("gemini", GEMINI_STUDIO_MODELS[3:] + ["gemini-2.0-flash"], 1.0),
    ]

    for provider, wave_models, delay_sec in waves:
        if provider == "gemini" and not _has_valid_gemini_key():
            continue
        if provider == "openrouter" and not _has_valid_openrouter_key():
            continue
        if delay_sec > 0:
            time.sleep(delay_sec)

        for model_name in wave_models:
            try:
                if provider == "openrouter":
                    ans = _call_openrouter_single(messages, model_name, temperature=0.2)
                else:
                    ans = _call_google_ai_studio_single(messages, model_name, temperature=0.2, json_mode=False)
                if ans and ans.strip():
                    return ans.strip()
            except Exception as e:
                last_error = str(e)
                continue

    raise RuntimeError(f"خطا در دریافت پاسخ از مشاور هوشمند (OpenRouter / Google AI Studio): {last_error}")


def is_question_or_catalog_inquiry(text: str) -> bool:
    """
    تشخیص هوشمند اینکه پیام کاربر یک «سوال فنی / استعلام اشتراکات / موجودی لنت‌ها» است یا یک «سفارش صدور فاکتور»
    """
    t = (text or "").strip()
    if not t:
        return False

    # اگر صراحتاً کلمه فاکتور یا پیش‌فاکتور همراه با تعداد/سفارش آمده باشد، سفارش است مگر سوالی باشد
    order_triggers = ["فاکتور کن", "پیش فاکتور کن", "پیش‌فاکتور کن", "فاکتور بزن", "سفارش خانم", "سفارش آقای", "سفارش اقای"]
    if any(tr in t for tr in order_triggers) and "؟" not in t and "چی میخوره" not in t and "مشترک" not in t:
        return False

    qa_keywords = [
        "؟", "?", "اشتراک", "مشترک", "میخوره", "می‌خوره", "میخورد", "می‌خورد",
        "کدوم لنت", "کدام لنت", "چه لنت", "لنت چی", "لنت های", "لنت‌های",
        "لیست لنت", "سوال", "بپرسم", "شرایط خرید", "حداقل خرید", "چند دست",
        "کارتن", "سازگار", "معادل", "به چی میخوره", "به چه ماشینی", "دارید", "دارین",
    ]
    if any(kw in t for kw in qa_keywords):
        # بررسی کنیم اگر پیام حاوی الگوی سفارش چند قلمه نیست، سوال تلقی شود
        if not any(tr in t for tr in order_triggers):
            return True
    return False


def extract_order_from_text(user_text: str, catalog: list, order_mode: str = "wholesale") -> dict:
    cleaned_text = normalize_automotive_stt_text(user_text)
    system_prompt = build_system_prompt(catalog)
    messages = [
        {"role": "system", "content": system_prompt},
        {"role": "user", "content": cleaned_text},
    ]
    return call_openrouter_models(messages, FREE_TEXT_MODELS, catalog, source_text=cleaned_text, order_mode=order_mode)


def extract_order_from_image(image_bytes: bytes, mime_type: str, caption: str, catalog: list, order_mode: str = "wholesale") -> dict:
    system_prompt = build_system_prompt(catalog)
    b64_img = base64.b64encode(image_bytes).decode("utf-8")
    user_prompt = (
        "لطفاً تصویر این برگ سفارش/فاکتور را به دقت بخوانید و اقلام سفارش، تعداد، شیم‌دار بودن یا نبودن و نام مشتری را استخراج کرده و به صورت JSON برگردانید. "
        "توجه کنید: فقط اگر در تصویر یا توضیحات، نام لوازم یدکی/فروشگاه نوشته شده بود آن را در shop_name بگذارید وگرنه shop_name را خالی بگذارید."
    )
    if caption:
        user_prompt += f"\nتوضیحات تکمیلی کاربر همراه عکس: {caption}"

    messages = [
        {"role": "system", "content": system_prompt},
        {
            "role": "user",
            "content": [
                {"type": "text", "text": user_prompt},
                {
                    "type": "image_url",
                    "image_url": {"url": f"data:{mime_type};base64,{b64_img}"},
                },
            ],
        },
    ]
    return call_openrouter_models(messages, FREE_VISION_MODELS, catalog, source_text="", order_mode=order_mode)


def transcribe_audio_high_accuracy(audio_path: str, audio_format: str = "ogg") -> str:
    """
    تبدیل دقیق ویس فارسی به متن با:
    1. فیلتر حذف نویز و نرمال‌سازی بلندی صدا در ffmpeg (highpass + lowpass + dynaudnorm)
    2. دریافت همزمان بهترین کاندیداها از موتور گفتار گوگل (show_all=True) و انتخاب جمله‌ای که بیشترین تطابق با اصطلاحات لنت را دارد
    3. تصحیح خودکار اشتباهات آوایی رایج («باشیم» -> «با شیم»، «بدون سیم» -> «بدون شیم»، «پرایدی» -> «پراید» و...)
    """
    import speech_recognition as sr

    raw_text = ""
    with tempfile.TemporaryDirectory() as tmpdir:
        wav_path = os.path.join(tmpdir, "voice_clean.wav")
        # اعمال فیلترهای صوتی برای شفافیت صدای گوینده و حذف نویز محیط
        ffmpeg_cmd = [
            "ffmpeg", "-y", "-i", audio_path,
            "-af", "highpass=f=80,lowpass=f=8000,dynaudnorm",
            "-ar", "16000", "-ac", "1", wav_path
        ]
        res = subprocess.run(ffmpeg_cmd, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
        if res.returncode != 0:
            subprocess.run(
                ["ffmpeg", "-y", "-i", audio_path, "-ar", "16000", "-ac", "1", wav_path],
                check=True,
                stdout=subprocess.DEVNULL,
                stderr=subprocess.DEVNULL,
            )

        recognizer = sr.Recognizer()
        with sr.AudioFile(wav_path) as source:
            audio_data = recognizer.record(source)

        try:
            resp = recognizer.recognize_google(audio_data, language="fa-IR", show_all=True)
            if isinstance(resp, dict) and "alternative" in resp and resp["alternative"]:
                domain_terms = ["شیم", "لنت", "فاکتور", "میل", "جلو", "عقب", "دیسکی", "پراید", "پژو", "تیبا", "ریو"]
                best_alt = resp["alternative"][0].get("transcript", "")
                best_score = -1
                for alt in resp["alternative"]:
                    cand = alt.get("transcript", "")
                    norm_cand = normalize_automotive_stt_text(cand)
                    score = sum(2 for kw in domain_terms if kw in norm_cand)
                    if score > best_score:
                        best_score = score
                        best_alt = norm_cand
                raw_text = best_alt
            elif isinstance(resp, str):
                raw_text = resp
        except Exception as e:
            logger.warning(f"Google STT primary error: {e}")
            try:
                raw_text = recognizer.recognize_google(audio_data, language="fa-IR")
            except Exception as e2:
                logger.warning(f"Google STT simple fallback error: {e2}")

    # اگر سرویس گوگل در دسترس نبود، به صورت چرخشی از OpenRouter و Google AI Studio برای پیاده‌سازی متن ویس استفاده می‌کنیم
    if not raw_text:
        try:
            with open(audio_path, "rb") as f:
                b64_audio = base64.b64encode(f.read()).decode("utf-8")
            audio_messages = [
                {
                    "role": "user",
                    "content": [
                        {
                            "type": "text",
                            "text": "لطفاً این ویس سفارش لنت ترمز را کلمه به کلمه و دقیق به متن فارسی تبدیل کن (اصطلاحات با شیم، بدون شیم، ۵ میل، ۶ میل و نام خودروها را دقیق بنویس). فقط متن پیاده‌شده را بدون هیچ توضیح اضافه‌ای برگردان.",
                        },
                        {
                            "type": "input_audio",
                            "input_audio": {"data": b64_audio, "format": audio_format},
                        },
                    ],
                }
            ]
            audio_waves = [
                ("openrouter", FREE_AUDIO_MODELS),
                ("gemini", ["gemini-2.5-flash", "gemini-2.0-flash", "gemini-1.5-flash"]),
                ("openrouter", ["openrouter/free"]),
            ]
            for provider, a_models in audio_waves:
                if raw_text:
                    break
                if provider == "gemini" and not _has_valid_gemini_key():
                    continue
                if provider == "openrouter" and not _has_valid_openrouter_key():
                    continue
                for m_name in a_models:
                    try:
                        if provider == "openrouter":
                            txt = _call_openrouter_single(audio_messages, m_name, temperature=0.0)
                        else:
                            txt = _call_google_ai_studio_single(audio_messages, m_name, temperature=0.0, json_mode=False)
                        if txt:
                            raw_text = txt
                            break
                    except Exception as e_aud:
                        logger.warning(f"[{provider}] Audio fallback error on {m_name}: {e_aud}")
        except Exception as e:
            logger.warning(f"Audio transcription fallback error: {e}")

    if not raw_text:
        raise RuntimeError("متأسفانه صدای واضحی از ویس دریافت نشد. لطفاً مجدداً ویس بفرستید یا سفارش را تایپ کنید.")

    return normalize_automotive_stt_text(raw_text)


def apply_order_mode_pricing_to_items(items: list, order_mode: str = "wholesale") -> list:
    """بروزرسانی قیمت واحد اقلام بر اساس حالت سفارش (عمده یا خرد)"""
    for item in items:
        base_p = item.get("base_unit_price", item.get("unit_price"))
        final_p, pct = calculate_final_unit_price(
            base_p, item.get("row_id", ""), item.get("base_name", item.get("name", "")), order_mode
        )
        item["base_unit_price"] = base_p
        item["unit_price"] = final_p
        item["markup_percent"] = pct
    return items



def build_single_verified_item(matched: dict, qty: int, with_shim: bool, order_mode: str = "wholesale") -> dict:
    """ساخت دیکشنری استاندارد یک ردیف کالای سفارش بر اساس ردیف کاتالوگ، تعداد و وضعیت شیم"""
    base_unit_price = matched["price_with_shim"] if with_shim else matched["price_no_shim"]
    if base_unit_price is None:
        # اگر یک حالت (مثلاً با شیم یا بدون شیم) قیمت نداشت، حالت دیگر را بررسی می‌کنیم
        alt_price = matched["price_no_shim"] if with_shim else matched["price_with_shim"]
        if alt_price is not None:
            with_shim = not with_shim
            base_unit_price = alt_price

    final_unit_price, markup_pct = calculate_final_unit_price(
        base_unit_price, matched["row_id"], matched["name"], order_mode=order_mode
    )
    display_name = matched["name"]
    if with_shim and "شیم" not in display_name:
        display_name += " با شیم"

    return {
        "row_id": matched["row_id"],
        "wva": matched["wva"],
        "name": display_name,
        "base_name": matched["name"],
        "qty": max(1, int(qty)),
        "base_unit_price": base_unit_price,
        "unit_price": final_unit_price,
        "markup_percent": markup_pct,
        "with_shim": bool(with_shim),
        "compatible_cars": get_compatible_vehicles_for_item(matched["row_id"], matched["name"]),
    }


def has_two_backing_plate_models(row_id: str, catalog: list) -> tuple:
    """
    بررسی اینکه آیا این لنت در کاتالوگ ۲ مدل کفشک (۵ میل و ۶ میل یعنی X.1 و X.2) دارد یا خیر.
    خروجی: (True/False, row_5mm_dict, row_6mm_dict)
    """
    by_row = {c["row_id"]: c for c in catalog}
    s_clean = to_en_str(str(row_id).strip()).split("_")[0]
    m = re.match(r"^(\d+)", s_clean)
    if not m:
        return False, None, None
    base_num = m.group(1)
    r5 = by_row.get(f"{base_num}.1")
    r6 = by_row.get(f"{base_num}.2")
    if r5 and r6:
        return True, r5, r6
    return False, None, None


def validate_and_price_order(parsed: dict, catalog: list, source_text: str = "", order_mode: str = "wholesale") -> dict:
    """
    تطبیق قطعی قیمت‌ها با فایل اکسل، اعمال ضریب سفارش عمده/خرد و افزودن لیست خودروهای سازگار (اشتراکات)
    """
    by_row = {c["row_id"]: c for c in catalog}
    by_wva = {}
    for c in catalog:
        by_wva.setdefault(c["wva"].upper(), []).append(c)

    verified_items = []
    warnings = list(parsed.get("unavailable_warnings", []))

    for it in parsed.get("items", []):
        row_id = str(it.get("row_id", "")).strip()
        wva = str(it.get("wva", "")).strip().upper()
        qty = int(it.get("qty", 1))
        with_shim = bool(it.get("with_shim", False))

        matched = by_row.get(row_id)
        if not matched and wva in by_wva:
            matched = by_wva[wva][0]

        if not matched:
            warnings.append(f"کالای «{it.get('display_name', wva)}» در لیست اکسل یافت نشد.")
            continue

        base_unit_price = matched["price_with_shim"] if with_shim else matched["price_no_shim"]
        if base_unit_price is None:
            warnings.append(
                f"کالای «{matched['name']}» ({matched['wva']}) در حال حاضر در لیست قیمت خط تیره (-) است و قیمت ندارد."
            )
            continue

        final_unit_price, markup_pct = calculate_final_unit_price(
            base_unit_price, matched["row_id"], matched["name"], order_mode=order_mode
        )

        display_name = it.get("display_name") or matched["name"]
        if with_shim and "شیم" not in display_name:
            display_name += " با شیم"

        verified_items.append(
            {
                "row_id": matched["row_id"],
                "wva": matched["wva"],
                "name": display_name,
                "base_name": matched["name"],
                "qty": qty,
                "base_unit_price": base_unit_price,
                "unit_price": final_unit_price,
                "markup_percent": markup_pct,
                "with_shim": with_shim,
                "compatible_cars": get_compatible_vehicles_for_item(
                    matched["row_id"], matched["name"]
                ),
            }
        )

    final_customer_title = build_final_customer_title(parsed, source_text=source_text)

    return {
        "doc_type": parsed.get("doc_type", "پیش‌فاکتور"),
        "order_mode": order_mode,
        "customer_title": final_customer_title,
        "date": parsed.get("date") or get_today_jalali(),
        "invoice_no": parsed.get("invoice_no", "........................."),
        "items": verified_items,
        "warnings": warnings,
    }


